package com.nm.fragmentsclean.editorialIntelligenceContext.write.businesslogic.usecases;
import com.nm.fragmentsclean.editorialIntelligenceContext.write.businesslogic.gateways.TopicCandidateRepository; import jakarta.transaction.Transactional; import org.springframework.stereotype.Component; import java.util.UUID;
@Component public class DecideTopicCandidate {private final TopicCandidateRepository candidates;public DecideTopicCandidate(TopicCandidateRepository candidates){this.candidates=candidates;}@Transactional public void retain(UUID id){var c=load(id);c.retain();candidates.save(c);}@Transactional public void defer(UUID id){var c=load(id);c.defer();candidates.save(c);}@Transactional public void ignore(UUID id){var c=load(id);c.ignore();candidates.save(c);}private com.nm.fragmentsclean.editorialIntelligenceContext.write.businesslogic.models.TopicCandidate load(UUID id){return candidates.byId(id).orElseThrow(()->new IllegalStateException("Topic candidate not found: "+id));}}
